install.sh.body:
#!/bin/sh
set -eu

PROGRAM=habiter-installer
API_BASE=${HABITER_API_BASE:-https://get.habiter.dev}
CHANNEL=stable
VERSION=
DRY_RUN=0
VERBOSE=0
NO_DESKTOP=0
SYSTEM=0
INSTALL_DIR=
TMP_DIR=
BACKUP_PATH=
FINAL_PATH=

say() { printf '%s\n' "$*"; }
die() { printf '%s: %s\n' "$PROGRAM" "$*" >&2; exit 1; }
debug() { [ "$VERBOSE" -eq 0 ] || printf '      %s\n' "$*"; }
cleanup() {
  status=$?
  if [ "$status" -ne 0 ] && [ -n "$BACKUP_PATH" ] && [ -e "$BACKUP_PATH" ] && [ -n "$FINAL_PATH" ]; then
    rm -rf -- "$FINAL_PATH"
    mv -- "$BACKUP_PATH" "$FINAL_PATH"
  fi
  [ -z "$TMP_DIR" ] || rm -rf -- "$TMP_DIR"
  exit "$status"
}
trap cleanup EXIT HUP INT TERM

usage() {
  say "Habiter desktop installer"
  say "Usage: install.sh [--channel stable|beta] [--version X.Y.Z] [--install-dir PATH]"
  say "                  [--dry-run] [--verbose] [--no-color] [--system] [--no-desktop-integration]"
}

parse_args() {
  while [ "$#" -gt 0 ]; do
    case "$1" in
      --channel) [ "$#" -ge 2 ] || die "--channel requires a value"; CHANNEL=$2; shift 2 ;;
      --version) [ "$#" -ge 2 ] || die "--version requires a value"; VERSION=$2; shift 2 ;;
      --install-dir) [ "$#" -ge 2 ] || die "--install-dir requires a value"; INSTALL_DIR=$2; shift 2 ;;
      --dry-run) DRY_RUN=1; shift ;;
      --verbose) VERBOSE=1; shift ;;
      --no-color) NO_COLOR=1; export NO_COLOR; shift ;;
      --system) SYSTEM=1; shift ;;
      --no-desktop-integration) NO_DESKTOP=1; shift ;;
      --help|-h) usage; exit 0 ;;
      *) die "unknown option: $1" ;;
    esac
  done
  case "$CHANNEL" in stable|beta) ;; *) die "channel must be stable or beta" ;; esac
  [ -z "$VERSION" ] || printf '%s' "$VERSION" | grep -Eq '^[0-9]+\.[0-9]+\.[0-9]+$' || die "version must use X.Y.Z"
}

normalize_arch() {
  case "$1" in x86_64|amd64) say x64 ;; arm64|aarch64) say arm64 ;; *) return 1 ;; esac
}

normalize_distro() {
  id=$1; like=$2
  case "$id" in
    ubuntu|linuxmint|pop|debian)
      if [ "$id" = debian ]; then say debian; else say ubuntu; fi
      return
      ;;
    fedora|rhel|centos) say fedora; return ;;
    arch|manjaro|endeavouros) say arch; return ;;
    opensuse*|sles) say opensuse; return ;;
  esac
  case " $like " in *" debian "*) say debian ;; *" fedora "*|*" rhel "*) say fedora ;; *" arch "*) say arch ;; *" suse "*) say opensuse ;; *) say generic ;; esac
}

detect_system() {
  raw_os=${HABITER_UNAME_S:-$(uname -s)}
  raw_arch=${HABITER_UNAME_M:-$(uname -m)}
  ARCH=$(normalize_arch "$raw_arch") || die "unsupported architecture: $raw_arch"
  DISTRO=
  case "$raw_os" in
    Linux)
      OS=linux
      release_file=${HABITER_OS_RELEASE_FILE:-/etc/os-release}
      id=$(sed -n 's/^ID=//p' "$release_file" | head -n 1 | tr -d '"')
      like=$(sed -n 's/^ID_LIKE=//p' "$release_file" | head -n 1 | tr -d '"')
      DISTRO=$(normalize_distro "$id" "$like")
      ;;
    Darwin) OS=macos ;;
    *) die "unsupported operating system: $raw_os" ;;
  esac
  if [ "$OS" = macos ]; then
    if [ "$ARCH" = arm64 ]; then ARCH=arm64; else ARCH=x64; fi
  fi
}

json_string() { printf '%s' "$1" | sed -n "s/.*\"$2\":\"\([^\"]*\)\".*/\1/p"; }
json_number() { printf '%s' "$1" | sed -n "s/.*\"$2\":\([0-9][0-9]*\).*/\1/p"; }

resolve_release() {
  query="channel=$CHANNEL"
  [ -z "$VERSION" ] || query="$query&version=$VERSION"
  [ -z "$DISTRO" ] || query="$query&distro=$DISTRO"
  endpoint="$API_BASE/api/v1/install/$OS/$ARCH?$query"
  debug "Resolver: $endpoint"
  RESPONSE=$(curl -fsSL --proto '=https' --tlsv1.2 "$endpoint") || die "release resolver failed"
  RELEASE_VERSION=$(json_string "$RESPONSE" version)
  FORMAT=$(json_string "$RESPONSE" format)
  FILE_NAME=$(json_string "$RESPONSE" fileName)
  DOWNLOAD_URL=$(json_string "$RESPONSE" url)
  SHA256=$(json_string "$RESPONSE" sha256)
  SIZE=$(json_number "$RESPONSE" size)
  printf '%s' "$RELEASE_VERSION" | grep -Eq '^[0-9]+\.[0-9]+\.[0-9]+$' || die "resolver returned an invalid version"
  printf '%s' "$FILE_NAME" | grep -Eq '^[A-Za-z0-9][A-Za-z0-9._-]+$' || die "resolver returned an invalid file name"
  printf '%s' "$SHA256" | grep -Eq '^[a-f0-9]{64}$' || die "resolver returned an invalid checksum"
  printf '%s' "$SIZE" | grep -Eq '^[1-9][0-9]*$' || die "resolver returned an invalid size"
  case "$DOWNLOAD_URL" in https://*) ;; *) die "resolver returned a non-HTTPS URL" ;; esac
  case "$OS:$FORMAT" in linux:appimage|macos:zip) ;; *) die "unsupported installer artifact: $FORMAT" ;; esac
}

verify_sha256() {
  file=$1
  if command -v sha256sum >/dev/null 2>&1; then actual=$(sha256sum "$file" | awk '{print $1}')
  elif command -v shasum >/dev/null 2>&1; then actual=$(shasum -a 256 "$file" | awk '{print $1}')
  else die "sha256sum or shasum is required"; fi
  [ "$actual" = "$SHA256" ] || die "SHA-256 mismatch"
}

install_linux() {
  root=${INSTALL_DIR:-${HOME}/.local/opt/habiter}
  FINAL_PATH="$root/Habiter.AppImage"
  bin_dir=${HOME}/.local/bin
  desktop_dir=${HOME}/.local/share/applications
  [ "$SYSTEM" -eq 0 ] || { root=/opt/habiter; FINAL_PATH=$root/Habiter.AppImage; bin_dir=/usr/local/bin; desktop_dir=/usr/local/share/applications; }
  say "[5/7] Installing application"; say "      $FINAL_PATH"
  if [ "$DRY_RUN" -eq 1 ]; then return; fi
  mkdir -p "$root" "$bin_dir" "$desktop_dir"
  staged="$root/.Habiter.AppImage.new"; cp "$TMP_DIR/$FILE_NAME" "$staged"; chmod 755 "$staged"
  if [ -e "$FINAL_PATH" ]; then BACKUP_PATH="$root/.Habiter.AppImage.backup"; rm -f "$BACKUP_PATH"; mv "$FINAL_PATH" "$BACKUP_PATH"; fi
  mv "$staged" "$FINAL_PATH"
  if [ "$NO_DESKTOP" -eq 0 ]; then
    ln -sfn "$FINAL_PATH" "$bin_dir/habiter"
    printf '%s\n' '[Desktop Entry]' 'Type=Application' 'Name=Habiter' "Exec=$FINAL_PATH" 'Icon=dev.habiter.Habiter' 'Terminal=false' 'Categories=Utility;' > "$desktop_dir/dev.habiter.Habiter.desktop"
  fi
  [ -z "$BACKUP_PATH" ] || rm -f "$BACKUP_PATH"; BACKUP_PATH=
}

install_macos() {
  root=${INSTALL_DIR:-${HOME}/Applications}; [ "$SYSTEM" -eq 0 ] || root=/Applications
  FINAL_PATH="$root/Habiter.app"
  say "[5/7] Installing application"; say "      $FINAL_PATH"
  [ "$DRY_RUN" -eq 1 ] && return
  mkdir -p "$TMP_DIR/extracted" "$root"
  ditto -x -k "$TMP_DIR/$FILE_NAME" "$TMP_DIR/extracted"
  [ -d "$TMP_DIR/extracted/Habiter.app/Contents/MacOS" ] || die "archive does not contain a valid Habiter.app"
  staged="$root/.Habiter.app.new"; rm -rf "$staged"; mv "$TMP_DIR/extracted/Habiter.app" "$staged"
  if [ -e "$FINAL_PATH" ]; then BACKUP_PATH="$root/.Habiter.app.backup"; rm -rf "$BACKUP_PATH"; mv "$FINAL_PATH" "$BACKUP_PATH"; fi
  mv "$staged" "$FINAL_PATH"; [ -z "$BACKUP_PATH" ] || rm -rf "$BACKUP_PATH"; BACKUP_PATH=
}

main() {
  parse_args "$@"
  say "Habiter installer"; say ""
  say "[1/7] Detecting system"; detect_system; say "      $OS${DISTRO:+ · $DISTRO} · $ARCH"
  say "[2/7] Resolving release"; resolve_release; say "      $CHANNEL · $RELEASE_VERSION · $FORMAT"
  destination=${INSTALL_DIR:-user-scoped default}
  if [ "$DRY_RUN" -eq 1 ]; then
    say "[3/7] Dry run"; say "      Would download $FILE_NAME ($SIZE bytes)"; say "[4/7] SHA-256 verification"; say "      Would verify $SHA256"
  else
    TMP_DIR=$(mktemp -d "${TMPDIR:-/tmp}/habiter.XXXXXX")
    say "[3/7] Downloading"; say "      $FILE_NAME ($SIZE bytes)"
    curl -fL --proto '=https' --tlsv1.2 -o "$TMP_DIR/$FILE_NAME" "$DOWNLOAD_URL"
    say "[4/7] Verifying SHA-256"; verify_sha256 "$TMP_DIR/$FILE_NAME"; say "      OK  $SHA256"
  fi
  if [ "$OS" = linux ]; then install_linux; else install_macos; fi
  say "[6/7] Desktop integration"
  if [ "$NO_DESKTOP" -eq 0 ]; then say "      enabled"; else say "      skipped"; fi
  say "[7/7] Done"; say "      Version: $RELEASE_VERSION"; say "      Destination: ${FINAL_PATH:-$destination}"; say "      Run: habiter"
}

[ "${HABITER_TEST_MODE:-}" = functions ] || main "$@"

install.ps1.body:
# Habiter PowerShell installer
param(
    [ValidateSet('stable', 'beta')][string]$Channel = 'stable',
    [ValidatePattern('^$|^\d+\.\d+\.\d+$')][string]$Version = '',
    [string]$InstallDir = '',
    [switch]$DryRun,
    [switch]$VerboseOutput,
    [switch]$System,
    [switch]$NoDesktopIntegration
)

$ErrorActionPreference = 'Stop'
$ProgressPreference = 'SilentlyContinue'
$script:TempDirectory = $null
$script:BackupDirectory = $null
$script:FinalDirectory = $null
$ApiBase = if ($env:HABITER_API_BASE) { $env:HABITER_API_BASE } else { 'https://get.habiter.dev' }

function Write-Step([int]$Number, [string]$Message) { Write-Host "[$Number/7] $Message" }
function Write-Detail([string]$Message) { Write-Host "      $Message" }
function Write-DebugDetail([string]$Message) { if ($VerboseOutput) { Write-Detail $Message } }

function Get-NormalizedArchitecture([string]$Value) {
    if ([string]::IsNullOrWhiteSpace($Value)) { throw 'Unable to detect the Windows architecture.' }
    switch ($Value.ToLowerInvariant()) {
        { $_ -in @('amd64', 'x86_64', 'x64') } { return 'x64' }
        { $_ -in @('arm64', 'aarch64') } { return 'arm64' }
        default { throw "Unsupported architecture: $Value" }
    }
}

function Get-DetectedArchitecture($RuntimeArchitecture) {
    if ($null -ne $RuntimeArchitecture) {
        return Get-NormalizedArchitecture ([string]$RuntimeArchitecture)
    }
    foreach ($candidate in @($env:PROCESSOR_ARCHITEW6432, $env:PROCESSOR_ARCHITECTURE)) {
        if (-not [string]::IsNullOrWhiteSpace($candidate)) {
            return Get-NormalizedArchitecture $candidate
        }
    }
    throw 'Unable to detect the Windows architecture.'
}

function Assert-ResolverResponse($Response) {
    if ($Response.version -notmatch '^\d+\.\d+\.\d+$') { throw 'Resolver returned an invalid version.' }
    if ($Response.platform -ne 'windows' -or $Response.architecture -notin @('x64', 'arm64')) { throw 'Resolver returned an invalid target.' }
    if ($Response.artifact.format -ne 'zip') { throw 'Resolver did not return a Windows ZIP.' }
    if ($Response.artifact.fileName -notmatch '^[A-Za-z0-9][A-Za-z0-9._-]+$') { throw 'Resolver returned an invalid file name.' }
    if ($Response.artifact.url -notmatch '^https://') { throw 'Resolver returned a non-HTTPS URL.' }
    if ($Response.artifact.sha256 -notmatch '^[a-f0-9]{64}$') { throw 'Resolver returned an invalid checksum.' }
    if ([long]$Response.artifact.size -lt 1) { throw 'Resolver returned an invalid size.' }
}

function Resolve-HabiterRelease([string]$Architecture) {
    if ($env:HABITER_RESOLVER_JSON) {
        $response = $env:HABITER_RESOLVER_JSON | ConvertFrom-Json
    } else {
        $query = "channel=$Channel"
        if ($Version) { $query += "&version=$Version" }
        $uri = "$ApiBase/api/v1/install/windows/$Architecture`?$query"
        Write-DebugDetail "Resolver: $uri"
        $response = Invoke-RestMethod -Uri $uri -Method Get -MaximumRedirection 0 -Headers @{ Accept = 'application/json' }
    }
    Assert-ResolverResponse $response
    return $response
}

function Assert-HabiterChecksum([string]$Path, [string]$Expected) {
    $actual = (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant()
    if ($actual -ne $Expected) { throw 'SHA-256 mismatch. Installation aborted.' }
    return $actual
}

function Restore-PreviousInstall {
    if ($script:BackupDirectory -and (Test-Path -LiteralPath $script:BackupDirectory) -and $script:FinalDirectory) {
        Remove-Item -LiteralPath $script:FinalDirectory -Recurse -Force -ErrorAction SilentlyContinue
        Move-Item -LiteralPath $script:BackupDirectory -Destination $script:FinalDirectory
    }
}

function Install-DesktopIntegration([string]$Root) {
    $startMenuDirectory = if ($env:HABITER_START_MENU_DIR) { $env:HABITER_START_MENU_DIR } else { [Environment]::GetFolderPath('Programs') }
    New-Item -ItemType Directory -Path $startMenuDirectory -Force | Out-Null
    $startMenu = Join-Path $startMenuDirectory 'Habiter.lnk'
    $shell = New-Object -ComObject WScript.Shell
    $shortcut = $shell.CreateShortcut($startMenu)
    $shortcut.TargetPath = Join-Path $Root 'habiter.exe'
    $shortcut.WorkingDirectory = $Root
    $shortcut.Description = 'Habiter'
    $shortcut.Save()

    $binDirectory = Join-Path $Root 'bin'
    New-Item -ItemType Directory -Path $binDirectory -Force | Out-Null
    '@echo off' + [Environment]::NewLine + '"%~dp0..\habiter.exe" %*' | Set-Content -LiteralPath (Join-Path $binDirectory 'habiter.cmd') -Encoding Ascii
    if (-not $env:HABITER_SKIP_PATH_UPDATE) {
        $userPath = [Environment]::GetEnvironmentVariable('Path', 'User')
        $entries = @($userPath -split ';' | Where-Object { $_ })
        if ($entries -notcontains $binDirectory) {
            [Environment]::SetEnvironmentVariable('Path', (($entries + $binDirectory) -join ';'), 'User')
            Write-Detail "Added command directory to user PATH: $binDirectory"
        }
    }
}

function Invoke-HabiterInstall {
    Write-Host 'Habiter installer'
    Write-Host ''
    Write-Step 1 'Detecting system'
    $architecture = if ($env:HABITER_ARCHITECTURE) {
        Get-NormalizedArchitecture $env:HABITER_ARCHITECTURE
    } else {
        Get-DetectedArchitecture ([Runtime.InteropServices.RuntimeInformation]::OSArchitecture)
    }
    Write-Detail "Windows · $architecture"

    Write-Step 2 'Resolving release'
    $release = Resolve-HabiterRelease $architecture
    Write-Detail "$Channel · $($release.version) · $($release.artifact.format)"
    $root = if ($InstallDir) { $InstallDir } elseif ($System) { Join-Path $env:ProgramFiles 'Habiter' } else { Join-Path $env:LOCALAPPDATA 'Programs\Habiter' }
    $script:FinalDirectory = $root

    if ($DryRun) {
        Write-Step 3 'Dry run'
        Write-Detail "Would download $($release.artifact.fileName) ($($release.artifact.size) bytes)"
        Write-Step 4 'SHA-256 verification'
        Write-Detail "Would verify $($release.artifact.sha256)"
        Write-Step 5 'Installing application'
        Write-Detail "Would install the complete bundle to $root"
    } else {
        $tempRoot = if ($env:HABITER_TEMP_ROOT) { $env:HABITER_TEMP_ROOT } else { [IO.Path]::GetTempPath() }
        New-Item -ItemType Directory -Path $tempRoot -Force | Out-Null
        $script:TempDirectory = Join-Path $tempRoot ("habiter-" + [guid]::NewGuid().ToString('N'))
        New-Item -ItemType Directory -Path $script:TempDirectory | Out-Null
        $archive = Join-Path $script:TempDirectory $release.artifact.fileName
        Write-Step 3 'Downloading'
        Write-Detail "$($release.artifact.fileName) ($($release.artifact.size) bytes)"
        if ($env:HABITER_ARCHIVE_PATH) {
            Copy-Item -LiteralPath $env:HABITER_ARCHIVE_PATH -Destination $archive
        } else {
            Invoke-WebRequest -Uri $release.artifact.url -OutFile $archive -MaximumRedirection 5
        }
        Write-Step 4 'Verifying SHA-256'
        $actual = Assert-HabiterChecksum $archive $release.artifact.sha256
        Write-Detail "OK  $actual"
        $extracted = Join-Path $script:TempDirectory 'extracted'
        Expand-Archive -LiteralPath $archive -DestinationPath $extracted
        $executable = Get-ChildItem -LiteralPath $extracted -Filter habiter.exe -Recurse | Select-Object -First 1
        if (-not $executable) { throw 'Archive does not contain the complete Habiter Windows bundle.' }
        $bundle = $executable.Directory.FullName
        $parent = Split-Path $root -Parent
        New-Item -ItemType Directory -Path $parent -Force | Out-Null
        $staged = "$root.new"
        Remove-Item -LiteralPath $staged -Recurse -Force -ErrorAction SilentlyContinue
        Move-Item -LiteralPath $bundle -Destination $staged
        if (Test-Path -LiteralPath $root) {
            $script:BackupDirectory = "$root.backup"
            Remove-Item -LiteralPath $script:BackupDirectory -Recurse -Force -ErrorAction SilentlyContinue
            Move-Item -LiteralPath $root -Destination $script:BackupDirectory
        }
        Move-Item -LiteralPath $staged -Destination $root
        Write-Step 5 'Installing application'
        Write-Detail $root
        if (-not $NoDesktopIntegration) { Install-DesktopIntegration $root }
        if ($script:BackupDirectory) { Remove-Item -LiteralPath $script:BackupDirectory -Recurse -Force; $script:BackupDirectory = $null }
    }
    Write-Step 6 'Desktop integration'
    Write-Detail $(if ($NoDesktopIntegration) { 'skipped' } else { 'Start Menu and habiter command enabled' })
    Write-Step 7 'Done'
    Write-Detail "Version: $($release.version)"
    Write-Detail "Destination: $root"
    Write-Detail 'Run: habiter'
}

if ($env:HABITER_TEST_MODE -ne 'functions') {
    try { Invoke-HabiterInstall }
    catch { Restore-PreviousInstall; Write-Error $_; exit 1 }
    finally { if ($script:TempDirectory) { Remove-Item -LiteralPath $script:TempDirectory -Recurse -Force -ErrorAction SilentlyContinue } }
}
